using System;using System.Drawing;using System.Drawing.Imaging;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Threading;using System.Threading.Tasks;
namespace AgitCon {
 public sealed partial class PreviewPaste {
  string longVisualProblem="not-inspected";bool longVisionReadStarted;
  static bool LongCaption(IntPtr dialog){string reason;return LongCaption(dialog,out reason);}
  static bool LongCaption(IntPtr dialog,out string reason){int count=0,sends=0;bool empty=true,enabled=true;EnumWindow visit=(w,d)=>{string cls=Class(w);if(!IsWindowVisible(w))return true;if((cls=="Button"||cls.StartsWith("WindowsForms10.BUTTON",StringComparison.OrdinalIgnoreCase))&&Native.Title(w)=="전송"){sends++;enabled&=IsWindowEnabled(w);}if(cls=="Edit"||cls.StartsWith("RichEdit",StringComparison.OrdinalIgnoreCase)||cls.StartsWith("WindowsForms10.EDIT",StringComparison.OrdinalIgnoreCase)||cls.StartsWith("WindowsForms10.RICHEDIT",StringComparison.OrdinalIgnoreCase)){count++;empty&=EmptyEdit(w);enabled&=IsWindowEnabled(w);}return true;};EnumChildWindows(dialog,visit,IntPtr.Zero);
   reason="caption edits="+count+",empty="+empty+",enabled="+enabled+",native-sends="+sends;if(count!=1||!empty||!enabled||sends>1)return false;
   try{var root=System.Windows.Automation.AutomationElement.FromHandle(dialog);var buttons=root.FindAll(System.Windows.Automation.TreeScope.Descendants,new System.Windows.Automation.AndCondition(new System.Windows.Automation.PropertyCondition(System.Windows.Automation.AutomationElement.ControlTypeProperty,System.Windows.Automation.ControlType.Button),new System.Windows.Automation.PropertyCondition(System.Windows.Automation.AutomationElement.NameProperty,"전송")));reason+=",uia-sends="+buttons.Count;if(buttons.Count==0)return true;if(buttons.Count!=1)return false;reason+=",uia-enabled="+buttons[0].Current.IsEnabled+",uia-offscreen="+buttons[0].Current.IsOffscreen;return buttons[0].Current.IsEnabled&&!buttons[0].Current.IsOffscreen;}catch(Exception ex){reason+="/uia-error="+ex.GetType().Name;return false;}
  }
  static string BandHash(Bitmap image){using(var stream=new MemoryStream()){image.Save(stream,ImageFormat.Png);using(var sha=SHA256.Create())return Convert.ToBase64String(sha.ComputeHash(stream.ToArray()));}}
  internal static async Task<bool> LongBandLabels(Bitmap header,Bitmap footer,CancellationToken token,Action<string> trace=null){
   bool heading=false;foreach(int width in new[]{800,1120,1600})using(var top=ConfirmationVision.Resize(header,width,Math.Max(1,header.Height*width/header.Width))){var h=await ConfirmationVision.Ocr(top,token);int count=h.Lines.Count(l=>ConfirmationVision.Normal(l.Text)=="클립보드이미지전송");if(trace!=null)trace("ocr-header width="+width+",matches="+count);if(count>1)return false;if(count==1){heading=true;break;}}if(!heading)return false;
   // Exact button text remains mandatory. Crop whitespace, never correct OCR text.
   foreach(bool centered in new[]{false,true}){Rectangle crop=centered?new Rectangle(footer.Width/4,0,footer.Width/2,footer.Height):new Rectangle(0,0,footer.Width,footer.Height);using(var region=footer.Clone(crop,PixelFormat.Format32bppArgb))foreach(int width in new[]{400,800,1120,1600})using(var bottom=ConfirmationVision.Resize(region,width,Math.Max(1,region.Height*width/region.Width))){var b=await ConfirmationVision.Ocr(bottom,token);int count=b.Lines.Count(l=>ConfirmationVision.Normal(l.Text)=="전송");if(trace!=null)trace("ocr-send width="+width+",center="+centered+",matches="+count);if(count>1)return false;if(count==1)return true;}}return false;
  }
  async Task<Func<bool>> LongVisualStructure(IntPtr dialog,CancellationToken token){
   longVisionReadStarted=false;string reason;if(!LongCaption(dialog,out reason)){longVisualProblem=reason;return null;}Native.Rect rect;if(!DpiGeometry.GetRect(dialog,out rect)){longVisualProblem="geometry-unavailable";return null;}int width=rect.Right-rect.Left,height=rect.Bottom-rect.Top;
   longVisualProblem="geometry="+width+"x"+height;if(width<180||height<220||width>1800||height>2400)return null;int band=Math.Min(height/4,Math.Max(40,(int)(60*ConfirmationNavigator.Dpi(dialog)/96)));var top=new Rectangle(0,0,width,band);var bottom=new Rectangle(0,height-band,width,band);string stamp=DpiGeometry.Stamp(dialog),headHash,footHash;
   longVisionReadStarted=true;try{using(var header=ConfirmationNavigator.Capture(dialog,top))using(var footer=ConfirmationNavigator.Capture(dialog,bottom)){
    bool labels=await LongBandLabels(header,footer,token,stage=>longVisualProblem=stage);longVisualProblem="visual labels="+labels+",empty="+LongCaption(dialog)+" / "+longVisualProblem;if(!labels)return null;headHash=BandHash(header);footHash=BandHash(footer);
   }}catch(OperationCanceledException){throw;}catch(Exception ex){longVisualProblem="visual-unavailable/"+ex.GetType().Name;return null;}
   return ()=>{try{Native.Rect now;longVisualProblem="recheck-caption";if(!LongCaption(dialog))return false;longVisualProblem="recheck-geometry";if(DpiGeometry.Stamp(dialog)!=stamp||!DpiGeometry.GetRect(dialog,out now)||now.Left!=rect.Left||now.Top!=rect.Top||now.Right!=rect.Right||now.Bottom!=rect.Bottom)return false;using(var header=ConfirmationNavigator.Capture(dialog,top))using(var footer=ConfirmationNavigator.Capture(dialog,bottom)){longVisualProblem="header-pixels-changed";if(BandHash(header)!=headHash)return false;longVisualProblem="footer-pixels-changed";if(BandHash(footer)!=footHash)return false;longVisualProblem="visual-current";return true;}}catch(Exception ex){longVisualProblem="recheck-error/"+ex.GetType().Name;return false;}};
  }
  internal static void TestLongVision(){int checks=0;try{Task.Run(async()=>{foreach(int scale in new[]{1,2,3})using(var header=new Bitmap(400*scale,60*scale,PixelFormat.Format32bppArgb))using(var footer=new Bitmap(400*scale,60*scale,PixelFormat.Format32bppArgb))using(var font=new Font("맑은 고딕",12*scale,GraphicsUnit.Pixel)){
    using(var g=Graphics.FromImage(header)){g.Clear(Color.White);g.DrawString("클립보드 이미지 전송",font,Brushes.Black,20*scale,20*scale);}using(var g=Graphics.FromImage(footer)){g.Clear(Color.White);g.DrawString("전송",font,Brushes.Black,180*scale,20*scale);}
    if(!await LongBandLabels(header,footer,CancellationToken.None)){using(var top=ConfirmationVision.Resize(header,800,120))using(var bottom=ConfirmationVision.Resize(footer,800,120)){var h=await ConfirmationVision.Ocr(top,CancellationToken.None);var b=await ConfirmationVision.Ocr(bottom,CancellationToken.None);throw new Exception("Header/footer fixture OCR scale "+scale+": "+String.Join("|",h.Lines.Select(l=>l.Text))+" / "+String.Join("|",b.Lines.Select(l=>l.Text)));}}checks++;
    if(scale==1){using(var g=Graphics.FromImage(footer)){g.Clear(Color.White);g.DrawString("닫기",font,Brushes.Black,180*scale,20*scale);}if(await LongBandLabels(header,footer,CancellationToken.None))throw new Exception("Missing send button accepted");checks++;using(var g=Graphics.FromImage(footer)){g.Clear(Color.White);g.DrawString("전송",font,Brushes.Black,180*scale,20*scale);}}
    using(var g=Graphics.FromImage(header)){g.Clear(Color.White);g.DrawString("다른 창",font,Brushes.Black,20*scale,20*scale);}if(await LongBandLabels(header,footer,CancellationToken.None))throw new Exception("Foreign heading accepted");checks++;
   }}).GetAwaiter().GetResult();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"longcon-vision-test.txt"),"PASS "+checks+" Korean OCR header/footer fixture checks at 100/200/300%. No real window, clipboard or Kakao interaction.");}catch(Exception ex){File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"longcon-vision-test.txt"),"FAIL "+ex);Environment.ExitCode=1;}}
 }
}
